import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Derive card aspect from atlas source rect (512x320)
  const aspect = 512 / 320;
  // Choose a width that fits within the hub frame (left edge ~ -3.2)
  const width = 1.8;
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);

  // Load the texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.needsUpdate = true;
      material.map = tex;
    });
  }

  // No interactions – empty handlers
  mesh.userData.handlers = {};

  // Cleanup resources
  mesh.userData.cleanup = () => {
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
    // No GSAP timelines to kill
  };

  return mesh;
}
